package dev.rodrigosambade.seats;
import java.util.*;import java.util.concurrent.locks.*;
public final class Wagon{public enum Status{RESERVED,OCCUPIED,FULL,INVALID}public record Reservation(Status status,List<String>freeSeats){}private final boolean[][]occupied;private final ReadWriteLock lock=new ReentrantReadWriteLock(true);public Wagon(int rows,int cols){if(rows<=0||cols<=0)throw new IllegalArgumentException();occupied=new boolean[rows][cols];}public Reservation reserve(int row,int col){lock.writeLock().lock();try{if(row<0||col<0||row>=occupied.length||col>=occupied[0].length)return new Reservation(Status.INVALID,freeUnsafe());if(occupied[row][col])return new Reservation(isFullUnsafe()?Status.FULL:Status.OCCUPIED,freeUnsafe());occupied[row][col]=true;return new Reservation(Status.RESERVED,freeUnsafe());}finally{lock.writeLock().unlock();}}public List<String>freeSeats(){lock.readLock().lock();try{return freeUnsafe();}finally{lock.readLock().unlock();}}private boolean isFullUnsafe(){for(boolean[]r:occupied)for(boolean x:r)if(!x)return false;return true;}private List<String>freeUnsafe(){List<String>r=new ArrayList<>();for(int i=0;i<occupied.length;i++)for(int j=0;j<occupied[i].length;j++)if(!occupied[i][j])r.add(i+","+j);return List.copyOf(r);}}
